/**
 * Opening animation (Lucas, 2026-11-24): on a cold start the flame frame of the PerTube emblem
 * swells in with a little overshoot, then the white arrow slides into it. About 1.6 s over black;
 * a tap skips it. It plays once per process, never on a rotation, and not at all when the system
 * asks for no animations. The app is already being built underneath, so it costs no waiting.
 */
object IntroState {
    var shown = false
}

@Composable
fun IntroHost(enabled: Boolean, content: @Composable () -> Unit) {
    var intro by remember { mutableStateOf(enabled && !IntroState.shown) }
    LaunchedEffect(Unit) { IntroState.shown = true }
    Box(Modifier.fillMaxSize()) {
        content()
        if (intro) LogoIntro(onDone = { intro = false })
    }
}

private const val LogoW = 861f
private const val LogoH = 959f
private val Overshoot = CubicBezierEasing(0.34f, 1.56f, 0.64f, 1f)

/** One colour of the emblem: its contours in the frame and in the arrow ("x,y;x,y|x,y;x,y"). */
private class EmblemLayer(val argb: Long, val frameData: String, val arrowData: String)

private class DrawLayer(val color: Color, val frame: Path, val arrow: Path)

private fun shape(data: String): Path = Path().apply {
    fillType = PathFillType.EvenOdd
    if (data.isEmpty()) return@apply
    for (contour in data.split('|')) {
        var first = true
        for (point in contour.split(';')) {
            val xy = point.split(',')
            val x = xy[0].toFloat()
            val y = xy[1].toFloat()
            if (first) moveTo(x, y) else lineTo(x, y)
            first = false
        }
        close()
    }
}

@Composable
private fun LogoIntro(onDone: () -> Unit) {
    val reduced = rememberReducedMotion()
    val clock = remember { Animatable(0f) }
    LaunchedEffect(Unit) {
        if (reduced) {
            onDone()
            return@LaunchedEffect
        }
        clock.animateTo(1.6f, tween(1600, easing = LinearEasing))
        onDone()
    }
    val layers = remember { EmblemData.map { DrawLayer(Color(it.argb), shape(it.frameData), shape(it.arrowData)) } }
    Canvas(
        Modifier
            .fillMaxSize()
            .graphicsLayer { alpha = 1f - ((clock.value - 1.3f) / 0.3f).coerceIn(0f, 1f) }
            .background(Color.Black)
            .pointerInput(Unit) { detectTapGestures { onDone() } },
    ) {
        val t = clock.value
        val s = size.width * 0.5f / LogoW
        val ox = (size.width - LogoW * s) / 2f
        val oy = (size.height - LogoH * s) / 2f
        withTransform({
            translate(ox, oy)
            scale(s, s, Offset.Zero)
        }) {
            // The frame swells in, a little past its size and back.
            val f = Overshoot.transform((t / 0.5f).coerceIn(0f, 1f))
            val frameAlpha = (t / 0.25f).coerceIn(0f, 1f)
            val frameScale = 0.8f + 0.2f * f
            if (frameAlpha > 0f) withTransform({ scale(frameScale, frameScale, Offset(LogoW / 2f, LogoH / 2f)) }) {
                for (layer in layers) drawPath(layer.frame, layer.color, alpha = frameAlpha)
            }
            // The arrow slides in from the left.
            val u = FastOutSlowInEasing.transform(((t - 0.35f) / 0.5f).coerceIn(0f, 1f))
            if (u > 0f) withTransform({ translate(-(1f - u) * 170f, 0f) }) {
                for (layer in layers) drawPath(layer.arrow, layer.color, alpha = (u * 3f).coerceIn(0f, 1f))
            }
        }
    }
}

